struct file_clone_range {
    __s64 src_fd;      // Source file descriptor
    __u64 src_offset;
    __u64 src_length;  // Length of data to reflink
    __u64 dest_offset;
};

// ... Setup dest_fd (O_RDWR) and src_fd (O_RDONLY)

struct file_clone_range fcr = {
    .src_fd = src_fd,
    .src_offset = 0,
    .src_length = 4096,
    .dest_offset = 0
};

// Reflink a specific data range (Copy-on-Write enabled)
int res = ioctl(dest_fd, FICLONERANGE, &fcr);

